import {wordChoices,productChoices} from './pattern-games.mjs';
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const button=(action,label,value)=>`<button class="btn" data-action="${action}" ${value===undefined?'':`data-value="${value}"`}>${label}</button>`;
export function patternArt(g){return `<div class="strategy-mini" aria-hidden="true">${{'word-search':'A → B ↴','unique-window':'[a b c] a',robber:'2 · 7 · 9',jump:'0 ⤳ 1 ⤳ 4','max-product':'−2 × −3 = 6'}[g.id]}</div>`;}
export function patternBoard(g,s){
 const r=g.rounds[s.round];let title,subtitle,body,steps;
 if(g.id==='word-search'){
  title='Trace a path. Undo a dead end.';subtitle=s.done?'Search complete.':s.path.length?`Next letter: ${r.word[s.path.length]}. Only orthogonal neighbors can continue this path.`:`Choose a starting ${r.word[0]}, or finish if every start failed.`;
  const cols=r.grid[0].length,options=wordChoices(r,s),tried=s.tried[s.path.join(',')]||[];
  body=`<div class="target-word">WORD <b>${r.word}</b><span>Matched: ${esc(r.word.slice(0,s.path.length))||'—'}</span></div><div class="word-grid" style="--columns:${cols}" role="group" aria-label="Word search board">${[...r.grid.join('')].map((c,i)=>`<button class="word-cell ${s.path.includes(i)?'in-path':''} ${options.includes(i)?'candidate':''} ${tried.includes(i)?'tried':''}" data-action="cell" data-value="${i}" ${s.done?'disabled':''} aria-label="Row ${Math.floor(i/cols)}, column ${i%cols}, ${c}${s.path.includes(i)?', path step '+s.path.indexOf(i):''}"><small>${Math.floor(i/cols)},${i%cols}</small><strong>${c}</strong><span>${s.path.includes(i)?'step '+s.path.indexOf(i):tried.includes(i)?'tried':' '}</span></button>`).join('')}</div><p class="viz-caption">Green: available matching choices · orange: current path · faded: tried from this prefix. Coordinates and path steps start at 0.</p><div class="queue-box"><strong>CURRENT PATH · CALL STACK</strong><div>${s.path.length?s.path.map(i=>`(${Math.floor(i/cols)}, ${i%cols})`).join(' → '):'Empty — try an untried start'}</div></div><div class="record-row"><div>Backtracks<strong>${s.backtracks}</strong></div></div><div class="controls">${s.done?'':button('back','Backtrack one cell')+button('absent','All paths failed · return false')}</div>`;
  steps=['Match the next letter using an unused adjacent cell. The same cell cannot appear twice in one path.','When a branch has no untried matching neighbor, backtrack one cell. Undo the visit so other paths may use it.','A complete word returns true. Only return false after every possible start fails.'];
 }else if(g.id==='unique-window'){
  title='Keep the window free of repeats.';const duplicate=r.values.slice(s.left,s.right).includes(r.values[s.right]);
  subtitle=s.right===r.values.length?'All characters processed. Finish with the best length.':duplicate?`“${r.values[s.right]}” is already in the window. Shrink from the left.`:`“${r.values[s.right]}” can enter the window. Expand right.`;
  body=`<div class="window-strip">${r.values.map((c,i)=>`<div class="window-cell ${i>=s.left&&i<s.right?'inside':''} ${i===s.right&&duplicate?'repeat-next':''}"><small>index ${i}</small><strong>${esc(c)}</strong><span>${i===s.left?'L ':''}${i===s.right?'R':''}</span></div>`).join('')}</div><p class="viz-caption">Window [L, R) excludes R. Current: ${esc(r.values.slice(s.left,s.right).join(''))||'empty'}. ${s.right===r.values.length?'R is at the end.':''}</p><div class="record-row"><div>Current length<strong>${s.right-s.left}</strong></div><div>Best length<strong>${s.best}</strong></div></div><div class="controls">${s.done?'':button('expand','Add next character →')+button('shrink','Remove leftmost character →')+button('finish','Finish scan')}</div>`;
  steps=['Before adding the next character, check whether it is already in the current window.','If it repeats, remove characters from the left until the repeat is gone. Never move left backward.','Expand and save the largest window length. The answer is a contiguous substring length.'];
 }else if(g.id==='robber'){
  title='Compare taking this house with skipping it.';subtitle='Each saved answer is the best total for a prefix. The choices are alternative plans, not permanent picks.';
  const take=s.done?0:r.values[s.index]+s.dp[Math.max(0,s.index-1)],skip=s.dp[s.index];
  body=`<div class="house-row">${r.values.map((v,i)=>`<div class="dp-cell house-cell ${i===s.index?'current':''}"><small>house ${i}</small><strong>${v}</strong><span>best = ${s.dp[i+1]??'?'}</span></div>`).join('')}</div>${s.done?'':`<div class="decision-pair"><div><small>TAKE CURRENT HOUSE</small><strong>${r.values[s.index]} + ${s.dp[Math.max(0,s.index-1)]} = ${take}</strong><span>Value + best before the neighboring house</span></div><div><small>SKIP CURRENT HOUSE</small><strong>${skip}</strong><span>Best through the previous house</span></div></div>`}<div class="controls">${s.done?'':button('take',`Save take · ${take}`)+button('skip',`Save skip · ${skip}`)}</div>`;
  steps=['Taking house i excludes house i − 1, so add its value to the best answer through i − 2.','Skipping house i keeps the best answer through i − 1. Compare both totals.','Save the larger prefix total. Two previous totals are enough to implement the recurrence.'];
 }else if(g.id==='jump'){
  title='Extend the frontier of reachable positions.';subtitle=s.farthest>=r.values.length-1?'The last index is within reach.':s.index>s.farthest?'The next index lies beyond the reachable frontier.':`Process index ${s.index}. Its jump can reach index ${s.index+r.values[s.index]}.`;
  const dx=460/Math.max(1,r.values.length-1),x=i=>30+i*dx;
  body=`<svg class="jump-viz" viewBox="0 0 520 125" role="img" aria-label="Reachable frontier ends at index ${Math.min(s.farthest,r.values.length-1)}">${r.values.slice(0,Math.min(s.index,r.values.length)).map((v,i)=>v===0?'':`<path d="M ${x(i)} 100 Q ${(x(i)+x(Math.min(i+v,r.values.length-1)))/2} 5 ${x(Math.min(i+v,r.values.length-1))} 100" stroke="#9b87ba" fill="none" stroke-width="2"/>`).join('')}<line x1="30" y1="108" x2="${x(Math.min(s.farthest,r.values.length-1))}" y2="108" stroke="#99b484" stroke-width="6"/></svg><div class="jump-row">${r.values.map((v,i)=>`<div class="dp-cell ${i<=s.farthest?'eligible':''} ${i===s.index?'current':''}"><small>index ${i}</small><strong>${v}</strong><span>${i===Math.min(s.farthest,r.values.length-1)?'frontier':i<=s.farthest?'reachable':'unreached'}</span></div>`).join('')}</div><p class="viz-caption">Each value is a maximum jump length. Arcs show processed jumps; green marks every reachable index.</p><div class="record-row"><div>Farthest reach<strong>${s.farthest}</strong></div></div><div class="controls">${s.done?'':button('extend','Extend frontier')+button('keep','Keep frontier')+button('reachable','Last index reachable · true')+button('blocked','Gap blocks progress · false')}</div>`;
  steps=['Only process an index if an earlier jump can reach it.','Compare the saved frontier with index + jump length and keep the larger endpoint.','Reaching the last index means true. Encountering an index beyond the frontier means false.'];
 }else{
  title=s.done?'Both extremes preserved the answer.':`Save the ${s.phase==='high'?'largest':'smallest'} product ending here.`;subtitle='Use the same previous min/max pair for both updates. You can also start a new subarray at the current value.';
  const options=s.done?[]:productChoices(r,s);
  body=`<div class="product-row">${r.values.map((v,i)=>`<div class="dp-cell ${i===s.index?'current':''}"><small>index ${i}</small><strong>${v}</strong><span>min: ${s.history[i]?.low??'?'}</span><span>max: ${s.history[i]?.high??'?'}</span></div>`).join('')}</div><div class="record-row"><div>Previous min<strong>${s.low??'—'}</strong></div><div>Previous max<strong>${s.high??'—'}</strong></div><div>Global best<strong>${s.best??'—'}</strong></div></div>${s.done?'':`<div class="product-candidates">${options.map((value,i)=>`<div><small>${i===0?'START FRESH':i===1?'EXTEND PREVIOUS MAX':'EXTEND PREVIOUS MIN'}</small><strong>${i===0?r.values[s.index]:`${r.values[s.index]} × ${i===1?s.high:s.low}`} = ${value}</strong></div>`).join('')}</div>${s.phase==='low'?`<p class="viz-caption">Pending new max: ${s.pendingHigh}. The previous pair stays unchanged until the minimum is saved.</p>`:''}<div class="controls">${[...new Set(options)].sort((a,b)=>a-b).map(n=>button(s.phase,`Save ${s.phase==='high'?'max':'min'} · ${n}`,n)).join('')}</div>`}`;
  steps=['At each value, consider a fresh start and extensions of both previous products.','Save the largest and smallest candidates. A negative number can swap their roles.','Update the global maximum from the new largest ending product. Keep subarrays nonempty.'];
 }
 const feedback=s.message?`<p class="feedback ${s.error?'error':''}">${esc(s.message)}${s.done?`<br><strong>${s.round+1===g.rounds.length?'Pattern unlocked. Opening your coding exercise…':'Loading the next round…'}</strong>`:''}</p>`:'';
 return `<div class="game-layout"><section class="game-board advanced-board"><div class="board-top"><span>ROUND ${s.round+1} OF ${g.rounds.length}</span><span class="target">${g.tag}</span></div><h2 class="instruction">${title}</h2><p class="subtext">${subtitle}</p>${body}<div id="game-feedback" aria-live="polite">${feedback}</div></section><aside class="explanation"><div class="icon">✳</div><h2>${g.concept}</h2><ol>${steps.map(t=>`<li>${t}</li>`).join('')}</ol><div class="divider">Explore each decision.<br>Wrong moves explain the invariant.</div></aside></div>`;
}
